#include <stdio.h>
#include <stdlib.h>

char *read_line(FILE *in, size_t *length)
{
    size_t capacity = 16;
    size_t used = 0;
    char *text = malloc(capacity);
    if (text == NULL) return NULL;
    int c;
    while ((c = fgetc(in)) != EOF && c != '\n') {
        if (used + 1 >= capacity) {
            char *bigger = realloc(text, capacity * 2);
            if (bigger == NULL) {
                free(text);
                return NULL;
            }
            text = bigger;
            capacity *= 2;
        }
        text[used++] = (char)c;
    }
    if (c == EOF && used == 0) {
        free(text);
        return NULL;
    }
    text[used] = '\0';
    *length = used;
    return text;
}

int main(void)
{
    char **lines = NULL;
    size_t *lengths = NULL;
    size_t count = 0;
    size_t capacity = 0;
    char *line;
    size_t length = 0;
    while ((line = read_line(stdin, &length)) != NULL) {
        if (count == capacity) {
            size_t new_capacity = capacity == 0 ? 8 : capacity * 2;
            char **more_lines = realloc(lines, new_capacity * sizeof *more_lines);
            if (more_lines == NULL) break;
            lines = more_lines;
            size_t *more_lengths = realloc(lengths, new_capacity * sizeof *more_lengths);
            if (more_lengths == NULL) break;
            lengths = more_lengths;
            capacity = new_capacity;
        }
        lines[count] = line;
        lengths[count] = length;
        count++;
    }
    for (size_t i = count; i > 0; i--) {
        printf("%zu (%zu):", i, lengths[i - 1]);
        if (lengths[i - 1] > 0) printf(" %s", lines[i - 1]);
        printf("\n");
        free(lines[i - 1]);
    }
    free(lines);
    free(lengths);
    return 0;
}
